/* Source: src/tokens.css */
/* Author: @jiuyi0204 | 森邮之间批准图色彩，结构切片。 */
:root {
 --sen-paper:#f5f0df; --sen-page:#e4dbc1; --sen-ink:#203e30;
 --sen-leaf:#526348; --sen-line:#53664c; --sen-soft:#e8e6d3;
 --sen-rust:#85552f; --sen-focus:#946a30; --sen-clear:transparent;
 --sen-font:"Senyou Serif","Source Han Serif SC","Songti SC",SimSun,serif;
 --sen-avatar:184px; --sen-ornament-width:850px;
 --st-theme-mobile-reading-width:42rem; --st-theme-mobile-reading-padding:1rem;
}



/* Source: src/kernel/fonts.css */
