/* Source: src/kernel/scrollbars.css */
/*
 * v7 固定全局无滚动条外观内核。
 * 只隐藏浏览器滚动条外观，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、跳转键、功能按钮或 input[type="range"]。
 * 全局 * 是本项目唯一允许的无边界选择器例外，不得增加其他声明。
 */
::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}


/* Source: src/chat-layout.css */
/* 1.14.0 index.html:7039 message_template; no generated people/text. */
body {background-color:var(--sen-page)}
#bg1 {background-color:var(--sen-page);background-image:url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/cb033bce23dd27950733fbd91010e654800499ce/assets/%E6%A3%AE%E9%82%AE%E4%B9%8B%E9%97%B4/forest-paper.png")!important;background-size:cover;background-position:center}
#chat {background:var(--sen-clear);border:0;padding:10px 0;gap:12px;text-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none}
#chat .mes[is_system="false"] {
 display:flex;flex-direction:column;align-items:stretch;flex-shrink:0;
 box-sizing:border-box;inline-size:100%;padding:38px 0 30px;margin:0;
 border:1px solid var(--sen-line);border-radius:4px;background-color:var(--sen-paper);background-image:url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/cb033bce23dd27950733fbd91010e654800499ce/assets/%E6%A3%AE%E9%82%AE%E4%B9%8B%E9%97%B4/paper-tile.png");background-size:640px;color:var(--sen-ink);
}
/* Full ornament occupies a real message parent; only decorative pseudo-element is layered. */
#chat .mes[is_system="false"] > .mesAvatarWrapper {
 position:relative;isolation:isolate;align-self:center;inline-size:100%;max-inline-size:100%;min-inline-size:0;
 padding-block:var(--sen-art-top) var(--sen-art-bottom);padding-inline:0;
 margin-inline:auto;text-align:center;box-sizing:border-box;overflow:clip;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper::before {
 content:"";display:block;position:absolute;top:0;left:calc(50% - var(--sen-art-left));
 width:var(--sen-art-width);height:var(--sen-art-height);background-image:var(--sen-frame-image);
 background-repeat:no-repeat;background-size:100% 100%;pointer-events:none;z-index:1;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar {
 inline-size:var(--sen-avatar);block-size:var(--sen-avatar);margin-inline:auto;
 border:0;outline:1px solid var(--sen-line);border-radius:2px;box-sizing:border-box;flex:none;position:relative;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar > img {
 width:100%;height:100%;max-height:none;border:0;border-radius:0;box-shadow:none;object-fit:cover;object-position:center;
}
#chat .mes[is_system="false"] > .mes_block {inline-size:100%;min-inline-size:0;padding:0;box-sizing:border-box}
#chat .mes[is_system="false"] > .mes_block > .ch_name {flex-direction:column;align-items:stretch;gap:5px;padding:0 12px 8px}
#chat .mes[is_system="false"] > .mes_block > .ch_name > .flex-container {justify-content:center;min-inline-size:0;flex:0 1 auto}
#chat .mes[is_system="false"] .ch_name .alignItemsBaseline {justify-content:center;align-items:center;flex-direction:column;gap:4px;min-inline-size:0;max-inline-size:100%}
#chat .mes[is_system="false"] .name_text {font-family:var(--sen-font);font-size:1.25em;font-weight:400;color:var(--sen-ink);overflow-wrap:anywhere;text-align:center}
#chat .mes[is_system="false"] .timestamp {color:var(--sen-leaf);font-family:var(--sen-font);font-size:.85em;text-align:center}
#chat .mes[is_system="false"] > .mes_block > .mes_text {
 inline-size:min(100%,64rem);max-inline-size:100%;margin-inline:auto!important;padding:6px clamp(20px,4%,56px);box-sizing:border-box;
}
/* Native actions stay attached to message; expanded tools flow below metadata. */
#chat .mes[is_system="false"] .ch_name > .mes_buttons {position:absolute;inset-block-start:8px;inset-inline-end:10px;max-inline-size:calc(100% - 20px);flex-wrap:wrap}
body.expandMessageActions #chat .mes[is_system="false"] .ch_name > .mes_buttons,
#chat .mes[is_system="false"] .ch_name > .mes_buttons:has(.extraMesButtons.visible) {position:static;align-self:stretch;max-inline-size:100%}
#chat .mes[is_system="false"] .extraMesButtons {flex-wrap:wrap}
#chat .mes[is_system="false"] .mes_edit_buttons {float:none;flex-wrap:wrap;align-self:center;max-inline-size:100%;filter:none;gap:6px}
#chat .mes.selected {background-color:var(--sen-soft);outline:2px solid var(--sen-rust);outline-offset:-3px}
#chat .mes[is_system="true"] {color:var(--sen-ink);background:var(--sen-paper)}
#chat .mes[is_system="false"][is_user="true"] {
 --sen-art-width:calc(var(--sen-avatar) * 4.643979);--sen-art-height:calc(var(--sen-avatar) * 2.321990);
 --sen-art-left:calc(var(--sen-avatar) * 2.314136);--sen-art-top:calc(var(--sen-avatar) * 0.642670);
 --sen-art-bottom:calc(calc(var(--sen-avatar) * 0.679319) + 8px);
 --sen-frame-image:url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/cb033bce23dd27950733fbd91010e654800499ce/assets/%E6%A3%AE%E9%82%AE%E4%B9%8B%E9%97%B4/user-frame.png");
}
#chat .mes[is_system="false"][is_user="false"] {
 --sen-art-width:calc(var(--sen-avatar) * 4.254197);--sen-art-height:calc(var(--sen-avatar) * 2.127098);
 --sen-art-left:calc(var(--sen-avatar) * 1.946043);--sen-art-top:calc(var(--sen-avatar) * 0.501199);
 --sen-art-bottom:calc(calc(var(--sen-avatar) * 0.625899) + 8px);
 --sen-frame-image:url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/cb033bce23dd27950733fbd91010e654800499ce/assets/%E6%A3%AE%E9%82%AE%E4%B9%8B%E9%97%B4/character-frame.png");
}
@media (max-width:700px) {
 :root {--sen-avatar:142px;--sen-ornament-width:100%}
#chat .mes[is_system="false"][is_user="true"] {
 --sen-art-width:calc(var(--sen-avatar) * 2.496552);--sen-art-height:calc(var(--sen-avatar) * 1.872414);
 --sen-art-left:calc(var(--sen-avatar) * 1.281897);--sen-art-top:calc(var(--sen-avatar) * 0.420690);
 --sen-art-bottom:calc(calc(var(--sen-avatar) * 0.451724) + 8px);
 --sen-frame-image:url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/cb033bce23dd27950733fbd91010e654800499ce/assets/%E6%A3%AE%E9%82%AE%E4%B9%8B%E9%97%B4/user-frame-mobile.png");
}
#chat .mes[is_system="false"][is_user="false"] {
 --sen-art-width:calc(var(--sen-avatar) * 2.522648);--sen-art-height:calc(var(--sen-avatar) * 1.891986);
 --sen-art-left:calc(var(--sen-avatar) * 1.274390);--sen-art-top:calc(var(--sen-avatar) * 0.421603);
 --sen-art-bottom:calc(calc(var(--sen-avatar) * 0.470383) + 8px);
 --sen-frame-image:url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/cb033bce23dd27950733fbd91010e654800499ce/assets/%E6%A3%AE%E9%82%AE%E4%B9%8B%E9%97%B4/character-frame-mobile.png");
}
 #chat {padding:8px;gap:10px}
 #chat .mes[is_system="false"] {flex-direction:column;align-items:stretch;padding-block:38px 28px}
 #chat .mes[is_system="false"] > .mesAvatarWrapper {margin-inline:auto;align-self:center}
 #chat .mes[is_system="false"] > .mes_block {inline-size:100%;min-inline-size:0}
 #chat .mes[is_system="false"] > .mes_block > .mes_text {inline-size:min(100%,var(--st-theme-mobile-reading-width));margin-inline:auto!important;padding-inline:var(--st-theme-mobile-reading-padding)!important}
}



/* Source: src/full-text.css */
/* 森邮之间：原生显隐、图标生成、事件与几何保留；文字采用常规字重。 */
#chat .mes_text {
  color: var(--sen-ink) !important;
  font-family: var(--sen-font) !important;
  font-weight: 400 !important;
  font-size: 1em !important;
  line-height: 1.85 !important;
  overflow-wrap: anywhere !important;
}

#chat .mes_text p {
  margin-block: 0 .8em !important;
}

#chat .mes_text p:last-child {
  margin-bottom: 0 !important;
}

#chat .mes[is_user="true"] .mes_text {
  text-align: center !important;
}

#chat .mes_text :is(h1,h2,h3,h4,h5,h6,strong,b) {
  color: var(--sen-ink) !important;
  font-family: var(--sen-font) !important;
  font-weight: 400 !important;
  line-height: 1.5 !important;
}

#chat .mes_text :is(em,i,q,blockquote) {
  color: var(--sen-leaf) !important;
}

#chat .mes_text blockquote {
  border-inline-start: 3px solid var(--sen-line) !important;
  padding-inline: 1em !important;
  margin-inline: 0 !important;
  background: var(--sen-soft) !important;
}

#chat .mes_text a {
  color: var(--sen-rust) !important;
  text-decoration: underline !important;
}

#chat .mes_text a:focus-visible {
  outline: 2px solid var(--sen-focus) !important;
  outline-offset: 2px !important;
}

#chat :is(.mes_text,.mes_reasoning) code {
  color: var(--sen-ink) !important;
  background-color: var(--sen-soft) !important;
  border-color: var(--sen-line) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
  box-shadow: none !important;
  font-family: var(--sen-font) !important;
  font-weight: 400 !important;
}

#chat :is(.mes_text,.mes_reasoning) pre {
  color: var(--sen-ink) !important;
  background-color: var(--sen-soft) !important;
  border-color: var(--sen-line) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
  box-shadow: none !important;
  font-family: var(--sen-font) !important;
  font-weight: 400 !important;
  border: 1px solid var(--sen-line) !important;
  padding: 12px !important;
  max-width: 100% !important;
  overflow-x: auto !important;
}

#chat :is(.mes_text,.mes_reasoning) pre code.hljs {
  color: var(--sen-ink) !important;
  background-color: var(--sen-soft) !important;
  border-color: var(--sen-line) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
  box-shadow: none !important;
  font-family: var(--sen-font) !important;
  font-weight: 400 !important;
}

#chat :is(.mes_text,.mes_reasoning) code.hljs [class*="hljs-"] {
  color: var(--sen-ink) !important;
  background-color: var(--sen-clear) !important;
  border-color: var(--sen-clear) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
  box-shadow: none !important;
  font-family: var(--sen-font) !important;
  font-weight: 400 !important;
}

#chat :is(.mes_text,.mes_reasoning) code.hljs :is(.hljs-string,.hljs-comment,.hljs-quote,.hljs-punctuation,.hljs-operator) {
  color: var(--sen-leaf) !important;
  background-color: var(--sen-clear) !important;
  border-color: var(--sen-clear) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
  box-shadow: none !important;
  font-family: var(--sen-font) !important;
  font-weight: 400 !important;
}

#chat :is(.mes_text,.mes_reasoning) code.hljs :is(.hljs-keyword,.hljs-number,.hljs-title,.hljs-name,.hljs-built_in,.hljs-literal,.hljs-attr,.hljs-symbol,.hljs-variable,.hljs-meta,.hljs-type,.hljs-regexp,.hljs-deletion,.hljs-addition) {
  color: var(--sen-rust) !important;
  background-color: var(--sen-clear) !important;
  border-color: var(--sen-clear) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
  box-shadow: none !important;
  font-family: var(--sen-font) !important;
  font-weight: 400 !important;
}

#chat :is(.mes_text,.mes_reasoning) ::selection {
  color: var(--sen-paper) !important;
  background-color: var(--sen-line) !important;
  border-color: var(--sen-line) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
  box-shadow: none !important;
}

#chat .mes_text table {
  display: block !important;
  overflow-x: auto !important;
  max-width: 100% !important;
}

#chat .mes_text :is(th,td) {
  border: 1px solid var(--sen-line) !important;
  padding: .45em .7em !important;
}

#chat .mes_text img {
  max-width: 100% !important;
  height: auto !important;
}


